expressionInfos.expression:
var m = $feature.HEIGHT_P50_M;
if (IsEmpty(m)) { return 'no estimate'; }
return Text(m, '#,##0.0') + ' m (' + Text($feature.HEIGHT_P50_FT, '#,##0') + ' ft)';

var m = $feature.HEIGHT_P95_M;
if (IsEmpty(m)) { return 'no estimate'; }
return Text(m, '#,##0.0') + ' m (' + Text($feature.HEIGHT_P95_FT, '#,##0') + ' ft)';

var c = $feature.ROOF_COV_PCT;
if (IsEmpty(c)) { return 'none'; }
return Text(c, '#,##0') + '% of the footprint\'s 0.5 m cells have lidar roof points';

var words = Dictionary("LOW_ROOF_SUPPORT", "Lidar roof points cover less than 80% of the footprint, so the height is less certain.", "NO_ROOF_SUPPORT", "No lidar roof points fall inside the footprint, so no height was estimated.", "NO_CELL_CENTERS", "The footprint is too small to hold a 0.5 m cell centre, so no height was estimated.", "NEGATIVE_HEIGHT", "Some roof cells sit below the ground surface; the footprint may not match the building.", "PARTIAL_AOI", "Part of the footprint lies outside the lidar coverage.", "GEOMETRY_REPAIRED", "The county footprint's shape was repaired before measuring.");
var parts = Split(DefaultValue($feature.HEIGHT_STATUS, ''), ';');
var out = [];
for (var i in parts) { if (HasKey(words, parts[i])) { Push(out, words[parts[i]]); } }
return IIf(Count(out) == 0, 'None beyond the estimate warning.', Concatenate(out, ' '));

var a = $feature.FOOTPRINT_M2;
if (IsEmpty(a)) { return 'unknown'; }
return Text(a, '#,##0') + ' m² (' + Text(a * 10.7639, '#,##0') + ' ft²)';

renderer.valueExpression:
var z = $feature.ZONE_ID;
if (z == 'CITY' || z == 'OWNERSHIP:PUBLIC_GOVERNMENT') { return null; }
return $feature.CANOPY_PCT;

expressionInfos.expression:
var d = $feature.CANOPY_PCT - $feature.CANOPY_PCT_OCT19;
if (Abs(d) < 0.005) { return 'The same as'; }
return Text(Abs(d), '0.00') + ' points ' + IIf(d < 0, 'below', 'above');
